def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, '_data'):
        raise AttributeError("Record object has no attribute '_data'")

    if not keys:
        return list(self._data.values())

    result = []
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError("Index out of range")
            result.append(list(self._data.values())[key])
        elif isinstance(key, str):
            if key not in self._data:
                raise KeyError(f"Key '{key}' not found")
            result.append(self._data[key])
        else:
            raise TypeError("Invalid key type; must be int or str")

    return result

def data(self, *keys):
    result = {}
    if not keys:
        for key, value in self.record.items():
            result[key] = value
    else:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self.record):
                    raise IndexError("Out-of-bounds index specified")
                result[self.record.keys()[key]] = self.record.values()[key]
            elif isinstance(key, str):
                if key not in self.record:
                    result[key] = None
                else:
                    result[key] = self.record[key]
            else:
                raise TypeError("Invalid key type")
    return result

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to the nearest even number.

    :param n: The number to round.
    :return: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an integer or float")

    if n >= 0:
        return int(n + 0.5 - 0.5 * (n + 0.5) % 1)
    else:
        return int(n - 0.5 + 0.5 * (n - 0.5) % 1)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not name or not fields or not srid_map:
        raise ValueError("name, fields, and srid_map must be provided")

    if not isinstance(name, str):
        raise TypeError("name must be a string")

    if not isinstance(fields, list) or not all(isinstance(field, str) for field in fields):
        raise TypeError("fields must be a list of strings")

    if not isinstance(srid_map, dict) or not all(isinstance(key, str) and isinstance(value, int) for key, value in srid_map.items()):
        raise TypeError("srid_map must be a dictionary with string keys and integer values")

    class Point:
        def __init__(self, *args, **kwargs):
            if len(args) != len(fields):
                raise ValueError(f"Expected {len(fields)} arguments, but got {len(args)}")
            for field, value in zip(fields, args):
                setattr(self, field, value)

        def __repr__(self):
            return f"{name}({', '.join(f'{field}={getattr(self, field)}' for field in fields)})"

    Point.__name__ = name
    Point.srid_map = srid_map

    return Point

