def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if cache_key in cache:
                return cache[cache_key]
            if lock is not None:
                lock.acquire()
            try:
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
            finally:
                if lock is not None:
                    lock.release()
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = OrderedDict()
        cache_times = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(kwargs.items()))
            now = timer()

            # Remove expired items
            cache = {k: v for k, (v, t) in cache.items() if now - t <= ttl}
            cache_times = {k: t for k, t in cache_times.items() if now - t <= ttl}

            if key in cache:
                cache_times[key] = now
                return cache[key]

            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                cache.popitem(last=False)
                cache_times.popitem(last=False)
            cache[key] = result
            cache_times[key] = now
            return result

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()
        hit = 0
        miss = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hit, miss
            key = args if not typed else (args, tuple(kwargs.items()))
            if key in cache:
                hit += 1
                cache.move_to_end(key)
                return cache[key]
            else:
                miss += 1
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

        wrapper.cache_info = lambda: (hit, miss, maxsize, len(cache))
        return wrapper

    return decorator

