def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to store the inheritance relationships
    inheritance = {cls: set() for cls in classes}
    for cls in classes:
        for base in cls.__bases__:
            if base in classes:
                inheritance[cls].add(base)

    # Find the minimal bases
    minimal = []
    for cls in classes:
        if not any(inheritance[base].issubset(inheritance[cls]) for base in classes if base != cls):
            minimal.append(cls)

    # Sort the minimal bases
    minimal.sort(key=classes.index)

    return minimal

