def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    result = {}
    for key in d1:
        if key not in d2:
            result[key] = copy.deepcopy(d1[key])
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            diff = difference(d1[key], d2[key], level - 1)
            if diff:
                result[key] = diff
        elif d1[key] != d2[key]:
            result[key] = d1[key]

    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.edges[0] or coord > self.edges[-1]:
        return
    index = bisect.bisect_left(self.edges, coord)
    if index < len(self.bins):
        self.bins[index] += weight

def _validate_labels(labels: Dict[str, Union[str, List[str]]]) -> None:
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, str) or not key_regex.match(key):
            errors.append({str(key): "Label key '{}' does not match the regex".format(key)})
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str) or not value_regex.match(v):
                    errors.append({str(v): "expected string or bytes-like object"})
        elif not isinstance(value, str) or not value_regex.match(value):
            errors.append({str(value): "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

