def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files or not digests_used:
        raise ValueError("Manifest files and digests used cannot be empty")

    for manifest_file in manifest_files:
        try:
            with open(manifest_file, 'r') as file:
                manifest_content = file.read()
                for digest in digests_used:
                    if digest not in manifest_content:
                        raise ValueError(f"Digest {digest} not found in manifest file {manifest_file}")
        except FileNotFoundError:
            raise FileNotFoundError(f"Manifest file {manifest_file} not found")
        except Exception as e:
            raise Exception(f"Error processing manifest file {manifest_file}: {e}")

    print("All required digests are present and used in the manifest files.")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict) or 'versions' not in inventory:
        raise ValueError("Invalid inventory format")
    if not isinstance(version, str) or version not in inventory['versions']:
        raise ValueError("Invalid version")

    logical_path_map = {}
    for logical_path, file_info in inventory['versions'][version].items():
        if 'content_files' in file_info:
            logical_path_map[logical_path] = set(file_info['content_files'])

    return logical_path_map

