def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid get_coordinate value. Must be 'left', 'right', or 'middle'.")

    if len(field_names) != 2:
        raise ValueError("Invalid number of field_names. Must be 2.")

    if scale is not None and scale not in [True, False]:
        raise ValueError("Invalid scale value. Must be True or False.")

    graph_points = []
    for bin_ in hist:
        value = make_value(bin_)
        if not isinstance(value, (int, float)):
            raise ValueError("make_value must return a numeric value.")

        if get_coordinate == "left":
            coordinate = bin_.x
        elif get_coordinate == "right":
            coordinate = bin_.x + bin_.width
        elif get_coordinate == "middle":
            coordinate = bin_.x + bin_.width / 2

        graph_points.append((coordinate, value))

    graph = {
        "points": graph_points,
        "field_names": field_names,
        "scale": scale if scale is not None else "unknown"
    }

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate does not claim to provide interface {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names())
    missing_methods = required_methods - candidate_methods

    if missing_methods:
        raise zope.interface.Invalid(f"Missing methods: {', '.join(missing_methods)}")

    for method_name in required_methods:
        method = getattr(candidate, method_name)
        if not callable(method):
            raise zope.interface.Invalid(f"Method {method_name} is not callable")

    candidate_attributes = set(dir(candidate))
    required_attributes = set(iface.names())
    missing_attributes = required_attributes - candidate_attributes

    if missing_attributes:
        raise zope.interface.Invalid(f"Missing attributes: {', '.join(missing_attributes)}")

    return True

