def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            subject = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject').text
            links = []
            for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                href = link.get('href')
                rel = link.get('rel')
                links.append({'href': href, 'rel': rel})
            return {'subject': subject, 'links': links}
        except ET.ParseError:
            raise ValueError("Invalid Diaspora webfinger document")

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        url = f"https://{handle}/.well-known/webfinger?resource=acct:{handle}"
        response = requests.get(url)
        response.raise_for_status()
        root = ET.fromstring(response.content)
        result = {}
        for link in root.findall(".//{http://www.w3.org/2005/Atom}link"):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                result[rel] = href
        return result
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document: {e}")
    except ET.ParseError as e:
        raise Exception(f"Failed to parse webfinger document: {e}")

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta")
        response.raise_for_status()
        root = ET.fromstring(response.content)
        return XRD(root)
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve host-meta document: {e}")
    except ET.ParseError as e:
        raise Exception(f"Failed to parse host-meta document: {e}")

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise ValueError("The first argument must be a dictionary")
    if not isinstance(val, (int, str, list, dict, tuple, set, bool, type(None))):
        raise ValueError("The value to insert must be a valid Python data type")
    if not isinstance(key, str):
        raise ValueError("The key must be a string")
    if not all(isinstance(k, str) for k in keys):
        raise ValueError("All sub keys must be strings")

    current_dict = dic
    for k in keys:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]
    current_dict[key] = val

