def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("Input must be a dictionary")

    include_key = "include"
    if include_key not in parser_dict:
        return parser_dict

    include_value = parser_dict[include_key]
    if not isinstance(include_value, dict):
        raise ValueError(f"Value of '{include_key}' must be a dictionary")

    for key, value in include_value.items():
        if key not in parser_dict:
            parser_dict[key] = value
        else:
            if not isinstance(parser_dict[key], dict):
                raise ValueError(f"Existing value for '{key}' must be a dictionary")
            parser_dict[key].update(value)

    del parser_dict[include_key]
    return parser_dict

